import{_ as p}from"./plugin-vue_export-helper-c27b6911.js";import{r as c,o,c as l,a as n,b as s,d as e,e as t}from"./app-4490560f.js";const i={},d=t(`<h1 id="cling-基于-llvm-的-c-交互式解释器" tabindex="-1"><a class="header-anchor" href="#cling-基于-llvm-的-c-交互式解释器" aria-hidden="true">#</a> cling（基于 LLVM 的 C++ 交互式解释器）</h1><blockquote><p>Homebrew 版本 1.2 ｜ 主页：见官方文档 ｜ 安装：<code>brew install cling</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>cling 是一个基于 <strong>LLVM/Clang</strong> 的 C++ 交互式解释器（interactive C++ interpreter），它提供了类似 Python 的 REPL 体验，但运行的是<strong>原生 C++</strong>。它解决的核心问题是：你不需要先写一个完整的 <code>.cpp</code> 文件、编译、链接、运行这一整套繁琐流程，就能逐行（或逐块）执行 C++ 表达式、声明变量、定义函数、包含头文件，并立即看到结果。</p><p>典型应用场景包括：快速验证算法逻辑、调试某段 C++ 代码片段、在交互式环境中探索 C++ 标准库和第三方库的 API、教学演示 C++ 语法、以及在科研或数据分析场景中把 C++ 当作脚本语言来使用。cling 也常作为 ROOT（CERN 的粒子物理分析框架）的底层解释引擎，把 C++ 代码直接绑定成可交互执行的脚本。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装 cling：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> cling

<span class="token comment"># 升级到最新版本</span>
brew upgrade cling

<span class="token comment"># 查看当前安装的版本</span>
cling <span class="token parameter variable">--version</span>

<span class="token comment"># 卸载</span>
brew uninstall cling
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证安装是否成功：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接进入交互式解释器</span>
cling

<span class="token comment"># 或查看版本信息</span>
cling <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 <code>brew install cling</code> 报错找不到包，可先执行 <code>brew update</code> 更新 Homebrew 的配方索引，再重试安装。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令 / 语法</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>cling</code></td><td>启动交互式 REPL</td><td><code>cling</code></td></tr><tr><td><code>cling --version</code></td><td>显示版本与 LLVM 信息</td><td><code>cling --version</code></td></tr><tr><td><code>cling 脚本.cpp</code></td><td>直接运行一个 C++ 源文件</td><td><code>cling demo.cpp</code></td></tr><tr><td><code>cling -l 库名</code> / <code>#include &lt;库&gt;</code></td><td>加载/包含头文件或库</td><td><code>cling -lstdc++</code></td></tr><tr><td><code>#include &lt;vector&gt;</code></td><td>在 REPL 内包含标准库头文件</td><td>在 cling 里输入 <code>#include &lt;vector&gt;</code></td></tr><tr><td><code>#pragma cling</code></td><td>各种 cling 扩展指令</td><td>见下文进阶技巧</td></tr><tr><td><code>.q</code> 或 <code>.quit</code></td><td>退出 cling 交互式会话</td><td>在 REPL 里输入 <code>.q</code></td></tr><tr><td><code>.help</code></td><td>查看内置命令帮助</td><td>在 REPL 里输入 <code>.help</code></td></tr><tr><td><code>.L 文件名.cpp</code></td><td>加载并解析一个文件到当前会话</td><td>在 REPL 里输入 <code>.L mylib.cpp</code></td></tr><tr><td><code>Ctrl+D</code></td><td>退出 REPL（EOF）</td><td>直接按 <code>Ctrl+D</code></td></tr></tbody></table><p>更多内置命令（在 REPL 内输入 <code>.help</code> 可查看完整列表）：</p><table><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>.L 文件</code></td><td>加载并解析文件到当前会话</td></tr><tr><td><code>.L 库.so</code> / <code>.L 库.dylib</code></td><td>加载动态库（等价于 <code>#pragma cling load</code>）</td></tr><tr><td><code>.x 文件</code></td><td>加载并执行一个文件（脚本模式）</td></tr><tr><td><code>.&gt; 文件</code></td><td>把后续输入重定向写入文件</td></tr><tr><td><code>.files</code></td><td>列出当前会话中已加载的所有文件</td></tr><tr><td><code>.g</code> / <code>.p</code></td><td>打印/显示已声明的全局对象</td></tr><tr><td><code>.U 符号</code></td><td>撤销（undeclare）之前声明的某个符号</td></tr><tr><td><code>.class 类名</code></td><td>打印一个类的布局与方法信息</td></tr><tr><td><code>.printAST</code></td><td>打印当前输入对应的抽象语法树（AST）</td></tr><tr><td><code>.I 目录</code></td><td>把目录加入头文件搜索路径（等价 <code>-I</code>）</td></tr><tr><td><code>.rawInput</code></td><td>切换是否按原始文本（非逐条解析）处理输入</td></tr><tr><td><code>.q</code> / <code>.quit</code></td><td>退出 cling</td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-进入-repl-并执行基本表达式" tabindex="-1"><a class="header-anchor" href="#示例-1-进入-repl-并执行基本表达式" aria-hidden="true">#</a> 示例 1：进入 REPL 并执行基本表达式</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 启动 cling</span>
cling

<span class="token comment"># 在 cling 提示符下输入以下内容（无需编译，逐行立即执行）</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int a <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int b <span class="token operator">=</span> <span class="token number">20</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> a + b
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>const int<span class="token punctuation">)</span> <span class="token number">30</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>int i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> ++i<span class="token punctuation">)</span> <span class="token punctuation">{</span> std::cout <span class="token operator">&lt;&lt;</span> i <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token number">0</span> <span class="token number">1</span> <span class="token number">2</span> 
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：<code>cling-1&gt;</code> 是 cling 的交互提示符。每行输入 <code>;</code> 结尾的语句会立即求值；表达式（不带分号）会打印结果。<code>(const int) 30</code> 即 <code>a + b</code> 的求值结果。按 <code>.q</code> 退出。</p></blockquote><h3 id="示例-2-在-repl-中使用标准库容器与算法" tabindex="-1"><a class="header-anchor" href="#示例-2-在-repl-中使用标准库容器与算法" aria-hidden="true">#</a> 示例 2：在 REPL 中使用标准库容器与算法</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;vector&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;algorithm&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> std::vector<span class="token operator">&lt;</span>int<span class="token operator">&gt;</span> <span class="token function">v</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token number">3</span>, <span class="token number">1</span>, <span class="token number">4</span>, <span class="token number">1</span>, <span class="token number">5</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> std::sort<span class="token punctuation">(</span>v.begin<span class="token punctuation">(</span><span class="token punctuation">)</span>, v.end<span class="token punctuation">(</span><span class="token punctuation">))</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>int x <span class="token builtin class-name">:</span> <span class="token function">v</span><span class="token punctuation">)</span> std::cout <span class="token operator">&lt;&lt;</span> x <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token number">1</span> <span class="token number">1</span> <span class="token number">3</span> <span class="token number">4</span> <span class="token number">5</span> 
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-编写脚本文件并直接运行" tabindex="-1"><a class="header-anchor" href="#示例-3-编写脚本文件并直接运行" aria-hidden="true">#</a> 示例 3：编写脚本文件并直接运行</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先创建一个 C++ 脚本文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> hello_cling.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
#include &lt;string&gt;

std::string greet(const std::string&amp; name) {
    return &quot;Hello, &quot; + name + &quot;!&quot;;
}

int main() {
    std::cout &lt;&lt; greet(&quot;cling&quot;) &lt;&lt; std::endl;
    return 0;
}
EOF</span>

<span class="token comment"># 用 cling 直接运行（不需要手动编译链接）</span>
cling hello_cling.cpp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>Hello, cling<span class="token operator">!</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="示例-4-repl-内加载并复用自定义源文件" tabindex="-1"><a class="header-anchor" href="#示例-4-repl-内加载并复用自定义源文件" aria-hidden="true">#</a> 示例 4：REPL 内加载并复用自定义源文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备一个工具函数文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> math_util.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
int square(int x) { return x * x; }
int cube(int x) { return x * x * x; }
EOF</span>

<span class="token comment"># 在 cling 会话中加载它并调用</span>
cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .L math_util.cpp
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> square<span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">25</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> cube<span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">27</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><code>.L 文件名</code> 会把文件内容解析进当前会话，之后定义的函数/变量即可直接使用。</p></blockquote><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-在-repl-内定义函数与类-实现-热插拔-式开发" tabindex="-1"><a class="header-anchor" href="#_1-在-repl-内定义函数与类-实现-热插拔-式开发" aria-hidden="true">#</a> 1. 在 REPL 内定义函数与类，实现&quot;热插拔&quot;式开发</h3><p>cling 支持在会话中随时重定义函数。若某个函数签名相同、实现变化，直接重新输入定义即可覆盖旧版本，非常适合边改边测：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int add<span class="token punctuation">(</span>int a, int b<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token builtin class-name">return</span> a + b<span class="token punctuation">;</span> <span class="token punctuation">}</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> add<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">5</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int add<span class="token punctuation">(</span>int a, int b<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token builtin class-name">return</span> a + b * <span class="token number">10</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>   // 重新定义
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> add<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">32</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>重定义对<strong>类</strong>同样有效。修改类的成员后重新声明，后续对象自动使用新布局：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> struct Point <span class="token punctuation">{</span> int x<span class="token punctuation">;</span> int y<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> Point p<span class="token punctuation">{</span><span class="token number">1</span>, <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">;</span> p.x
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">1</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> struct Point <span class="token punctuation">{</span> int x<span class="token punctuation">;</span> int y<span class="token punctuation">;</span> int z<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>   // 新增成员 z
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> Point q<span class="token punctuation">{</span><span class="token number">1</span>, <span class="token number">2</span>, <span class="token number">3</span><span class="token punctuation">}</span><span class="token punctuation">;</span> q.z
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">3</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-使用-pragma-cling-扩展指令控制加载与编译" tabindex="-1"><a class="header-anchor" href="#_2-使用-pragma-cling-扩展指令控制加载与编译" aria-hidden="true">#</a> 2. 使用 <code>#pragma cling</code> 扩展指令控制加载与编译</h3><p>cling 提供了一组 <code>#pragma cling</code> 指令，用于更精细地控制代码加载、优化和声明：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

<span class="token comment"># 临时关闭优化，方便调试</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling opt(0)</span>
<span class="token comment"># 加载共享库（链接动态库，例如某个 .so）</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling load(&quot;libmymodule.so&quot;)</span>
<span class="token comment"># 追加一个头文件搜索路径</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling add_include_path(&quot;/opt/homebrew/include&quot;)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在源文件里也可以直接写这些 pragma 指令，实现&quot;编译时控制&quot;。例如写一个带自加载的脚本头：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// config.hpp</span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">pragma</span> <span class="token expression">cling <span class="token function">add_include_path</span><span class="token punctuation">(</span></span><span class="token string">&quot;/opt/homebrew/include&quot;</span><span class="token expression"><span class="token punctuation">)</span></span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">pragma</span> <span class="token expression">cling <span class="token function">add_library_path</span><span class="token punctuation">(</span></span><span class="token string">&quot;/opt/homebrew/lib&quot;</span><span class="token expression"><span class="token punctuation">)</span></span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">pragma</span> <span class="token expression">cling <span class="token function">load</span><span class="token punctuation">(</span></span><span class="token string">&quot;libboost_system.dylib&quot;</span><span class="token expression"><span class="token punctuation">)</span></span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">pragma</span> <span class="token expression">cling <span class="token function">optimize</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span></span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用 <code>#pragma cling</code> 指令速查：</p><table><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>#pragma cling opt(N)</code></td><td>设置优化级别（0~3），0 关闭优化便于调试</td></tr><tr><td><code>#pragma cling optimize(N)</code></td><td>同上（别名）</td></tr><tr><td><code>#pragma cling load(&quot;库&quot;)</code></td><td>加载共享库（.so / .dylib / .a）</td></tr><tr><td><code>#pragma cling add_include_path(&quot;目录&quot;)</code></td><td>追加头文件搜索路径</td></tr><tr><td><code>#pragma cling add_library_path(&quot;目录&quot;)</code></td><td>追加库搜索路径</td></tr><tr><td><code>#pragma cling add_library(&quot;库名&quot;)</code></td><td>链接指定库</td></tr><tr><td><code>#pragma cling add_flag(&quot;-std=c++17&quot;)</code></td><td>传入额外的编译标志</td></tr><tr><td><code>#pragma cling add_include(&quot;头文件&quot;)</code></td><td>强制包含某个头文件</td></tr></tbody></table><h3 id="_3-与-make-cmake-产出的对象或库配合" tabindex="-1"><a class="header-anchor" href="#_3-与-make-cmake-产出的对象或库配合" aria-hidden="true">#</a> 3. 与 Make / CMake 产出的对象或库配合</h3><p>如果项目已经用 CMake 编译出静态库或动态库，你可以在 cling 会话中加载头文件并链接库，直接调用其 API 进行探索：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

<span class="token comment"># 假设项目产出 libmymath.a</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &quot;mymath.h&quot;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling load(&quot;libmymath.a&quot;)</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> mymath::add<span class="token punctuation">(</span><span class="token number">10</span>, <span class="token number">32</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">42</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>也可以直接在命令行指定包含路径和链接库，一次进入就可用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 命令行方式：指定头文件搜索路径并加载库</span>
cling -I/opt/homebrew/include <span class="token parameter variable">-lmymath</span>

<span class="token comment"># 或传入完整编译标志</span>
cling <span class="token parameter variable">-std</span><span class="token operator">=</span>c++17 <span class="token parameter variable">-O2</span> -I./include -L./lib <span class="token parameter variable">-lmymath</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-与其它工具搭配-在脚本中使用第三方-c-库" tabindex="-1"><a class="header-anchor" href="#_4-与其它工具搭配-在脚本中使用第三方-c-库" aria-hidden="true">#</a> 4. 与其它工具搭配：在脚本中使用第三方 C++ 库</h3><p>结合 Homebrew 安装的 C++ 库（如 <code>boost</code>、<code>eigen</code>），可以像脚本一样调用它们：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先安装依赖库</span>
brew <span class="token function">install</span> boost eigen

cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;eigen3/Eigen/Dense&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> Eigen::MatrixXd m<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m <span class="token operator">&lt;&lt;</span> <span class="token number">1</span>, <span class="token number">2</span>, <span class="token number">3</span>, <span class="token number">4</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m.inverse<span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：Eigen 等头文件库通常位于 <code>/opt/homebrew/include</code> 或 <code>/usr/local/include</code>，如果找不到，可以用 <code>-I</code> 指定头文件搜索路径：<code>cling -I/opt/homebrew/include</code> 或在 REPL 里用 <code>#pragma cling add_include_path</code> 添加。</p></blockquote><h3 id="_5-配置启动脚本-定制-repl-环境" tabindex="-1"><a class="header-anchor" href="#_5-配置启动脚本-定制-repl-环境" aria-hidden="true">#</a> 5. 配置启动脚本，定制 REPL 环境</h3><p>每次进入 cling 都手动包含一堆头文件很烦。可以写一个 <code>clingrc</code> 风格的初始化文件，用 <code>.L</code> 加载它：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 建立初始化文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> ~/.clingrc <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;string&gt;
#include &lt;algorithm&gt;

// 自定义便捷函数
void hello() { std::cout &lt;&lt; &quot;cling ready&quot; &lt;&lt; std::endl; }
EOF</span>

<span class="token comment"># 进入 cling 后加载</span>
cling
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .L ~/.clingrc
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> hello<span class="token punctuation">(</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> cling ready
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>若希望每个会话自动加载，可用 shell 别名封装：<code>alias cling=&quot;cling &amp;&amp; true&quot;</code> 或把 <code>.L ~/.clingrc</code> 写进你的 <code>.bashrc</code>/<code>.zshrc</code> 交互钩子。注意 cling 本身不自动读取 <code>~/.clingrc</code>，需要显式加载。</p></blockquote><h3 id="_6-通过命令行传参运行脚本-支持脚本化入参" tabindex="-1"><a class="header-anchor" href="#_6-通过命令行传参运行脚本-支持脚本化入参" aria-hidden="true">#</a> 6. 通过命令行传参运行脚本，支持脚本化入参</h3><p>用 <code>cling 脚本.cpp 参数...</code> 可以让脚本读取命令行参数。cling 会把后续参数放入一个全局字符串数组：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// argdemo.cpp</span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;vector&gt;</span></span>
<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">&amp;</span> a <span class="token operator">:</span> __cling_argv<span class="token punctuation">)</span> std<span class="token double-colon punctuation">::</span>cout <span class="token operator">&lt;&lt;</span> a <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span>
    std<span class="token double-colon punctuation">::</span>cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;\\nargc=&quot;</span> <span class="token operator">&lt;&lt;</span> __cling_argc <span class="token operator">&lt;&lt;</span> std<span class="token double-colon punctuation">::</span>endl<span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling argdemo.cpp alpha beta
<span class="token comment"># 输出：argdemo.cpp alpha beta</span>
<span class="token comment">#      argc=3</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：<code>__cling_argc</code> / <code>__cling_argv</code> 是 cling 注入的全局量，在解释执行时可用。若脚本以独立可执行方式编译则不可用，需改用标准 <code>main(int argc, char* argv[])</code>。</p></blockquote><h3 id="_7-调整解释器环境变量" tabindex="-1"><a class="header-anchor" href="#_7-调整解释器环境变量" aria-hidden="true">#</a> 7. 调整解释器环境变量</h3><p>cling 行为也受少量环境变量影响，常见的有：</p><table><thead><tr><th>环境变量</th><th>作用</th></tr></thead><tbody><tr><td><code>CLING_SKIP_CPUPROF</code></td><td>跳过某些 CPU 剖析初始化，减少启动开销</td></tr><tr><td><code>CLING_QUIET</code></td><td>关闭启动时的欢迎/版本横幅，输出更干净</td></tr><tr><td><code>CLING_ROOT</code></td><td>指向 cling 安装根目录，若路径迁移可用</td></tr></tbody></table><p>示例：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安静模式启动，适合脚本或 CI</span>
<span class="token assign-left variable">CLING_QUIET</span><span class="token operator">=</span><span class="token number">1</span> cling script.cpp

<span class="token comment"># 禁止 cling 尝试初始化 CPU 剖析</span>
<span class="token assign-left variable">CLING_SKIP_CPUPROF</span><span class="token operator">=</span><span class="token number">1</span> cling
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-交互式-repl-里表达式与语句的区别" tabindex="-1"><a class="header-anchor" href="#_1-交互式-repl-里表达式与语句的区别" aria-hidden="true">#</a> 1. 交互式 REPL 里表达式与语句的区别</h3><ul><li><strong>语句</strong>以分号 <code>;</code> 结尾：执行但不打印结果（<code>int a = 10;</code>）。</li><li><strong>表达式</strong>不带分号：立即求值并打印结果（<code>a + b</code>）。</li><li>新手最常见的坑是在 REPL 里打表达式时带了分号，结果什么也没输出——去掉分号再回车即可看到结果。</li></ul><h3 id="_2-版本与-llvm-依赖问题" tabindex="-1"><a class="header-anchor" href="#_2-版本与-llvm-依赖问题" aria-hidden="true">#</a> 2. 版本与 LLVM 依赖问题</h3><p>cling 依赖特定版本的 LLVM/Clang。若 <code>brew upgrade</code> 后 LLVM 版本与 cling 不匹配，可能出现加载头文件失败或奇怪崩溃。此时建议：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>brew doctor
brew upgrade cling
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>并确认 <code>cling --version</code> 显示的 LLVM 版本与 <code>clang --version</code> 一致。</p><h3 id="_3-头文件包含失败-找不到标准库头文件" tabindex="-1"><a class="header-anchor" href="#_3-头文件包含失败-找不到标准库头文件" aria-hidden="true">#</a> 3. 头文件包含失败 / 找不到标准库头文件</h3><p>若 <code>#include &lt;vector&gt;</code> 等报错找不到头文件，通常是编译器搜索路径配置问题。可显式指定路径：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling -I/opt/homebrew/include -I/opt/homebrew/include/c++/11.1.0
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><blockquote><p>Apple Silicon 机器用 <code>/opt/homebrew</code>，Intel 机器用 <code>/usr/local</code>。</p></blockquote><p>在 REPL 内也可用 <code>.I 目录</code> 命令或 <code>#pragma cling add_include_path(...)</code> 追加路径，无需重启会话：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .I /opt/homebrew/include
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_4-性能注意" tabindex="-1"><a class="header-anchor" href="#_4-性能注意" aria-hidden="true">#</a> 4. 性能注意</h3><p>cling 是解释/即时编译执行，<strong>速度远低于编译优化的二进制</strong>。CPU 密集的循环代码不要依赖 cling 跑性能基准；它更适合验证逻辑和交互调试。若追求性能，应把代码编译成可执行文件再运行。</p><p>若不得不在 cling 里做较重的计算，可临时提高优化级别：<code>#pragma cling opt(3)</code>。</p><h3 id="_5-多行代码的粘贴问题" tabindex="-1"><a class="header-anchor" href="#_5-多行代码的粘贴问题" aria-hidden="true">#</a> 5. 多行代码的粘贴问题</h3><p>在 REPL 里直接粘贴多行代码（如整个 <code>for</code> 循环）可能因换行/缩进被错误解析。建议：把完整代码写成 <code>.cpp</code> 文件，用 <code>.L 文件.cpp</code> 或 <code>cling 文件.cpp</code> 加载，而不是直接在交互式提示符粘贴大段代码。</p><p>若必须粘贴，可先输入 <code>.rawInput</code> 切换到原始输入模式，粘贴完成后再次输入 <code>.rawInput</code> 切回：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .rawInput
（粘贴多行代码，按两次回车结束）
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .rawInput
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-平台支持差异" tabindex="-1"><a class="header-anchor" href="#_6-平台支持差异" aria-hidden="true">#</a> 6. 平台支持差异</h3>`,85),r=n("code",null,"cling --version",-1),u={href:"https://github.com/root-project/cling",target:"_blank",rel:"noopener noreferrer"},k=t(`<h3 id="_7-常见报错与解决办法" tabindex="-1"><a class="header-anchor" href="#_7-常见报错与解决办法" aria-hidden="true">#</a> 7. 常见报错与解决办法</h3><table><thead><tr><th>报错 / 现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>fatal error: &#39;vector&#39; file not found</code></td><td>头文件搜索路径缺失</td><td>用 <code>-I</code> / <code>.I</code> / <code>add_include_path</code> 加入路径</td></tr><tr><td><code>error: no member named &#39;...&#39; in &#39;...&#39;</code></td><td>头文件未包含或命名空间不对</td><td>检查 <code>#include</code> 与 <code>using</code> / 完整限定名</td></tr><tr><td><code>undefined symbol</code> / 链接失败</td><td>动态库未加载或路径不对</td><td><code>#pragma cling load(&quot;库&quot;)</code> + <code>add_library_path</code></td></tr><tr><td><code>unexpected EOF while parsing</code></td><td>语句不完整/括号未闭合</td><td>补全括号或分号，检查多行粘贴</td></tr><tr><td><code>error: redefinition of &#39;...&#39;</code></td><td>同一符号重复定义</td><td>用 <code>.U 符号</code> 先撤销旧声明再重定义</td></tr><tr><td>启动即崩溃 / 段错误</td><td>LLVM 版本与 cling 不匹配</td><td><code>brew doctor</code> + 重装 cling，比对 LLVM 版本</td></tr><tr><td>找不到 eigen3 / boost 头文件</td><td>第三方库路径不在搜索范围</td><td><code>brew install</code> 后 <code>-I$(brew --prefix)/include</code></td></tr></tbody></table><h3 id="_8-内存与长会话注意" tabindex="-1"><a class="header-anchor" href="#_8-内存与长会话注意" aria-hidden="true">#</a> 8. 内存与长会话注意</h3><p>长时间运行的 cling 会话可能逐渐积累已解析的声明和缓存，内存占用缓慢上升。若发现响应变慢，可考虑重启会话；不建议在单会话内&quot;无限加载&quot;海量大型库。每个 <code>.L</code> 的文件会保留符号表，加载过多符号可能拖慢后续解析速度。</p><h3 id="_9-安全注意-不要直接解释不受信任的代码" tabindex="-1"><a class="header-anchor" href="#_9-安全注意-不要直接解释不受信任的代码" aria-hidden="true">#</a> 9. 安全注意：不要直接解释不受信任的代码</h3><p>cling 会直接执行你给的 C++ 代码，等价于原生代码执行权。<strong>不要加载来源不可信的脚本或库</strong>——它和运行任意二进制一样危险，可能访问文件、执行系统命令、修改系统。在多用户环境里也要避免给普通用户 cling 的超级权限解释能力。</p><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-与-root-集成-交互式粒子物理数据分析" tabindex="-1"><a class="header-anchor" href="#_1-与-root-集成-交互式粒子物理数据分析" aria-hidden="true">#</a> 1. 与 ROOT 集成：交互式粒子物理数据分析</h3><p>cling 是 ROOT 的底层解释引擎，二者天然配合。安装 ROOT 后，<code>root</code> 命令本质上是带 ROOT 库的 cling REPL：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装 ROOT（较慢，包含完整 cling）</span>
brew <span class="token function">install</span> root

<span class="token comment"># 启动 ROOT（其内部就是 cling 会话，可用 cling 语法）</span>
root

root <span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token comment">#include &lt;TH1F&gt;</span>
root <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> TH1F h<span class="token punctuation">(</span><span class="token string">&quot;h&quot;</span>, <span class="token string">&quot;demo&quot;</span>, <span class="token number">10</span>, <span class="token number">0</span>, <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
root <span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span> h.Fill<span class="token punctuation">(</span><span class="token number">20</span><span class="token punctuation">)</span><span class="token punctuation">;</span> h.Fill<span class="token punctuation">(</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span> h.Fill<span class="token punctuation">(</span><span class="token number">80</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
root <span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">]</span> h.Draw<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          // 弹出图形窗口
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在纯 cling 中也可以加载 ROOT 库来使用其类（需已安装 ROOT）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先让 cling 找到 ROOT 的头文件与库</span>
<span class="token builtin class-name">source</span> <span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span> root<span class="token variable">)</span></span>/bin/thisroot.sh
cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;TH1F&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling add_library_path(&quot;$(brew --prefix root)/lib&quot;)</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> TH1F h<span class="token punctuation">(</span><span class="token string">&quot;h&quot;</span>, <span class="token string">&quot;hist&quot;</span>, <span class="token number">5</span>, <span class="token number">0</span>, <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>int i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">100</span><span class="token punctuation">;</span> ++i<span class="token punctuation">)</span> h.Fill<span class="token punctuation">(</span>rand<span class="token punctuation">(</span><span class="token punctuation">)</span> % <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> h.GetMean<span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>教学/科研中常直接用 <code>root</code> 命令代替裸 <code>cling</code>，因为 ROOT 预置了大量数值、统计、绘图类。</p></blockquote><h3 id="_2-交互式探索与学习调试-c" tabindex="-1"><a class="header-anchor" href="#_2-交互式探索与学习调试-c" aria-hidden="true">#</a> 2. 交互式探索与学习调试 C++</h3><p>把 cling 当作&quot;语法练习场&quot;和&quot;调试沙盒&quot;：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 快速验证算法 / 数据结构行为</span>
cling
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;unordered_map&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> std::unordered_map<span class="token operator">&lt;</span>std::string, int<span class="token operator">&gt;</span> m<span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m<span class="token punctuation">[</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> m<span class="token punctuation">[</span><span class="token string">&quot;b&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m<span class="token punctuation">[</span><span class="token string">&quot;a&quot;</span><span class="token punctuation">]</span> + m<span class="token punctuation">[</span><span class="token string">&quot;b&quot;</span><span class="token punctuation">]</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">3</span>

<span class="token comment"># 查看类布局（学习对象内存模型）</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> struct S <span class="token punctuation">{</span> char c<span class="token punctuation">;</span> int i<span class="token punctuation">;</span> double d<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .class S
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// 把一段经常调试的代码写成 .cpp，用 .L 反复加载并打印中间量</span>
cat <span class="token operator">&gt;</span> debug_snippet<span class="token punctuation">.</span>cpp <span class="token operator">&lt;&lt;</span><span class="token char">&#39;EOF&#39;</span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;vector&gt;</span></span>
std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> <span class="token function">fizzbuzz</span><span class="token punctuation">(</span><span class="token keyword">int</span> n<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> r<span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> i <span class="token operator">&lt;=</span> n<span class="token punctuation">;</span> <span class="token operator">++</span>i<span class="token punctuation">)</span> r<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> r<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token constant">EOF</span>

cling
cling<span class="token operator">-</span><span class="token number">1</span><span class="token operator">&gt;</span> <span class="token punctuation">.</span>L debug_snippet<span class="token punctuation">.</span>cpp
cling<span class="token operator">-</span><span class="token number">1</span><span class="token operator">&gt;</span> <span class="token keyword">auto</span> v <span class="token operator">=</span> <span class="token function">fizzbuzz</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
cling<span class="token operator">-</span><span class="token number">1</span><span class="token operator">&gt;</span> v<span class="token punctuation">.</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
cling<span class="token operator">-</span><span class="token number">2</span><span class="token operator">&gt;</span> <span class="token punctuation">(</span><span class="token keyword">unsigned</span> <span class="token keyword">long</span><span class="token punctuation">)</span> <span class="token number">10</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>调试技巧：配合 <code>#pragma cling opt(0)</code> 关闭优化，可让局部变量与中间状态更贴近源码、更易观察。</p></blockquote><h3 id="_3-用-makefile-封装脚本化流程" tabindex="-1"><a class="header-anchor" href="#_3-用-makefile-封装脚本化流程" aria-hidden="true">#</a> 3. 用 Makefile 封装脚本化流程</h3><p>把常用的 cling 任务写进 <code>Makefile</code>，实现一键运行、批量处理：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile</span>
CXX        <span class="token operator">=</span> cling
CXXFLAGS   <span class="token operator">=</span> -I/opt/homebrew/<span class="token keyword">include</span> -std<span class="token operator">=</span>c++17

<span class="token comment"># 运行单个脚本</span>
<span class="token target symbol">run-%</span><span class="token punctuation">:</span>
	<span class="token variable">$</span><span class="token punctuation">(</span>CXX<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>CXXFLAGS<span class="token punctuation">)</span> <span class="token variable">$*.cpp</span>

<span class="token comment"># 批量运行当前目录下所有脚本</span>
<span class="token target symbol">all</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">patsubst</span> %.cpp,run-%,<span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">wildcard</span> *.cpp<span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token comment"># 对一组数据文件批量处理</span>
<span class="token target symbol">process</span><span class="token punctuation">:</span> process.cpp
	<span class="token variable">$</span><span class="token punctuation">(</span>CXX<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>CXXFLAGS<span class="token punctuation">)</span> process.cpp data_1.txt data_2.txt data_3.txt

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> run-% all process
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">make</span> run-hello_cling   <span class="token comment"># 等价于 cling -I/opt/homebrew/include -std=c++17 hello_cling.cpp</span>
<span class="token function">make</span> all               <span class="token comment"># 运行目录下所有 .cpp 脚本</span>
<span class="token function">make</span> process           <span class="token comment"># 带数据文件参数批量处理</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-在-ci-中做代码片段快速验证" tabindex="-1"><a class="header-anchor" href="#_4-在-ci-中做代码片段快速验证" aria-hidden="true">#</a> 4. 在 CI 中做代码片段快速验证</h3><p>cling 可作为 CI 的&quot;轻量冒烟测试&quot;：编译成本太高时，用 cling 解释执行验证逻辑正确性。示例 GitHub Actions：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/cling-check.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> cling<span class="token punctuation">-</span>check
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">check</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install cling
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          sudo apt-get update
          sudo apt-get install -y cling  # 或使用 conda/pip 渠道安装</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Run snippet check
        <span class="token key atrule">run</span><span class="token punctuation">:</span> cling tests/sanity_check.cpp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：不同发行版 cling 的安装渠道不同。Ubuntu 可尝试 <code>apt install cling</code>，或通过 Conda <code>conda install -c conda-forge cling</code>；macOS 用 Homebrew。CI 里务必锁定版本以保持 LLVM 一致性。</p></blockquote><h3 id="_5-批量处理与自动化-shell-循环" tabindex="-1"><a class="header-anchor" href="#_5-批量处理与自动化-shell-循环" aria-hidden="true">#</a> 5. 批量处理与自动化（shell 循环）</h3><p>用 cling 批量验证多个独立片段文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 对目录下所有片段做冒烟验证，任一失败即退出</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">f</span> <span class="token keyword">in</span> snippets/*.cpp<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== <span class="token variable">$f</span> ===&quot;</span>
  cling <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token operator">||</span> <span class="token punctuation">{</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;FAIL: <span class="token variable">$f</span>&quot;</span><span class="token punctuation">;</span> <span class="token builtin class-name">exit</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">done</span>

<span class="token comment"># 把多个参数批量传入同一个脚本</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">n</span> <span class="token keyword">in</span> <span class="token number">10</span> <span class="token number">100</span> <span class="token number">1000</span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  cling compute.cpp <span class="token string">&quot;<span class="token variable">$n</span>&quot;</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-生产级实践建议" tabindex="-1"><a class="header-anchor" href="#_6-生产级实践建议" aria-hidden="true">#</a> 6. 生产级实践建议</h3><ul><li><strong>职责划分</strong>：cling 只用于<strong>交互探索、原型验证、脚本化轻任务</strong>；生产环境的高性能、长期运行代码应编译为原生二进制。</li><li><strong>统一 LLVM 版本</strong>：项目里若有多个依赖 LLVM 的工具，务必对齐版本，否则头文件解析行为不一致。</li><li><strong>固定依赖路径</strong>：在脚本里用 <code>$(brew --prefix)</code> 或环境变量注入 include/lib 路径，避免写死绝对路径导致跨机器失效。</li><li><strong>编写可重入的脚本文件</strong>：把逻辑写成带 <code>main</code> 的 <code>.cpp</code>，这样既能被 <code>cling script.cpp</code> 解释运行，也能被 <code>g++/clang++</code> 编译成可执行文件，一份代码两种用途：</li></ul><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token comment">// portable_snippet.cpp —— 同时兼容 cling 与 g++/clang++</span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;iostream&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;vector&gt;</span></span>
<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> v <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">8</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
    std<span class="token double-colon punctuation">::</span><span class="token function">sort</span><span class="token punctuation">(</span>v<span class="token punctuation">.</span><span class="token function">begin</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> v<span class="token punctuation">.</span><span class="token function">end</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> x <span class="token operator">:</span> v<span class="token punctuation">)</span> std<span class="token double-colon punctuation">::</span>cout <span class="token operator">&lt;&lt;</span> x <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span>
    std<span class="token double-colon punctuation">::</span>cout <span class="token operator">&lt;&lt;</span> <span class="token string">&quot;\\n&quot;</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 解释运行（开发/验证）</span>
cling portable_snippet.cpp

<span class="token comment"># 编译运行（性能/生产）</span>
clang++ <span class="token parameter variable">-O2</span> <span class="token parameter variable">-o</span> portable portable_snippet.cpp <span class="token operator">&amp;&amp;</span> ./portable
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>日志与退出码</strong>：脚本化调用时检查 cling 的退出码（非 0 表示解析/执行出错），便于在 CI 和 shell 循环里捕获失败。</li></ul><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料" aria-hidden="true">#</a> 参考资料</h2>`,35),m={href:"https://github.com/root-project/cling",target:"_blank",rel:"noopener noreferrer"},v={href:"https://root.cern.ch",target:"_blank",rel:"noopener noreferrer"},b={href:"https://root.cern/cling/",target:"_blank",rel:"noopener noreferrer"},g=n("li",null,[s("Homebrew 配方："),n("code",null,"brew info cling")],-1);function h(f,_){const a=c("ExternalLinkIcon");return o(),l("div",null,[d,n("p",null,[s("cling 在 macOS（Apple Silicon）和 Linux 上的行为基本一致，但部分依赖 LLVM 的第三方扩展可能存在差异。遇到异常时，先确认 "),r,s(" 输出的 LLVM 版本号，并在"),n("a",u,[s("官方 GitHub 仓库"),e(a)]),s("的 Issues 里检索类似问题。")]),k,n("ul",null,[n("li",null,[s("cling 官方仓库："),n("a",m,[s("https://github.com/root-project/cling"),e(a)])]),n("li",null,[s("ROOT 项目（cling 的主要使用者）："),n("a",v,[s("https://root.cern.ch"),e(a)])]),n("li",null,[s("cling 文档（Jupyter/交互式用法）："),n("a",b,[s("https://root.cern/cling/"),e(a)])]),g])])}const y=p(i,[["render",h],["__file","cling.html.vue"]]);export{y as default};
